package com.greenocean.backend;
import com.greenocean.backend.auth.repository.UserRepository;import com.greenocean.backend.auth.service.TokenService;import jakarta.persistence.EntityManager;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;import org.junit.jupiter.api.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"greenocean.security.admin-enabled=true","greenocean.live-support.enabled=true"}) @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseN3OperationsTest {
 @Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired EntityManager entities;@Autowired MockMvc mvc;
 @Test @Tag("malicious") void dashboardRequiresCurrentRoleAndRecentSecurityKey()throws Exception{PhaseIFixtures.region(db);var actor=PhaseIFixtures.member(db,users,tokens);db.update("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE name='MODERATOR'",actor.id());entities.clear();actor=PhaseIFixtures.session(db,users,tokens,actor.id());mvc.perform(get("/api/v1/admin/listener-support/operations").header("Authorization","Bearer "+actor.token())).andExpect(status().isForbidden());db.update("UPDATE user_sessions SET mfa_authenticated_at=clock_timestamp() WHERE id=?",actor.session());mvc.perform(get("/api/v1/admin/listener-support/operations").header("Authorization","Bearer "+actor.token())).andExpect(status().isOk()).andExpect(jsonPath("$.alertsConfigured").value(false)).andExpect(jsonPath("$.retention.purgeEnabled").value(false)).andExpect(jsonPath("$.retention.retentionDays.BOOKING").value(30));db.update("DELETE FROM user_roles WHERE user_id=? AND role_id IN(SELECT id FROM roles WHERE name='MODERATOR')",actor.id());mvc.perform(get("/api/v1/admin/listener-support/operations").header("Authorization","Bearer "+actor.token())).andExpect(status().isUnauthorized());}
}
